// src/lib/mcp/tools/complete-tarefa.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z3 } from "npm:zod@^3.25.76";
var complete_tarefa_default = defineTool3({
  name: "complete_tarefa",
  title: "Marcar tarefa como feita",
  description: "Marca uma tarefa como conclu\xEDda pelo seu id.",
  inputSchema: {
    id: z3.string().min(1).describe("O id da tarefa.")
  },
  annotations: { readOnlyHint: false, idempotentHint: true, openWorldHint: false },
  handler: async ({ id }, ctx) => {
    requireAuth(ctx);
    const tarefas = await loadKey(ctx, "garcia:tarefas") ?? [];
    const idx = tarefas.findIndex((t) => t.id === id);
    if (idx < 0) {
      return { content: [{ type: "text", text: "Tarefa n\xE3o encontrada." }], isError: true };
    }
    tarefas[idx].feito = true;
    await saveKey(ctx, "garcia:tarefas", tarefas);
    return { content: [{ type: "text", text: `Tarefa "${tarefas[idx].texto}" conclu\xEDda.` }] };
  }
});

